/** Thai hint for an English dictation hint, or null when none is known. */
export function dictationHintTh(hintText: string | null | undefined): string | null {
  const key = (hintText ?? "").trim();
  return key ? (DICTATION_HINTS_TH[key] ?? null) : null;
}
